def compute_correlation(diff_trail, mask_trail, nb_rounds):
    """计算单条 trail 的相关度，并提取密钥条件"""
    conditions = [[[] for _ in range(64)] for _ in range(nb_rounds)]
    corr = 1
    for k in range(nb_rounds):
        for i in range(16):
            a = bin_to_int(diff_trail[k][0][4*i:4*i+4], SBOX_SIZE)
            b = bin_to_int(diff_trail[k][1][4*i:4*i+4], SBOX_SIZE)
            u = bin_to_int(mask_trail[k][0][4*i:4*i+4], SBOX_SIZE)
            v = bin_to_int(mask_trail[k][1][4*i:4*i+4], SBOX_SIZE)
            corr *= QDTM_GIFT_SBOX[b][a][v][u]
            if QDTM_GIFT_SBOX[b][a][v][u] == 0:
                return "Error"

    
    for k in range(nb_rounds):
        corr *= character([1], [mask_trail[k][1][0]], 1)
        corr *= character([(AC_STATES[k] >> 5) & 1], [mask_trail[k][1][40]], 1)
        corr *= character([(AC_STATES[k] >> 4) & 1], [mask_trail[k][1][44]], 1)
        corr *= character([(AC_STATES[k] >> 3) & 1], [mask_trail[k][1][48]], 1)
        corr *= character([(AC_STATES[k] >> 2) & 1], [mask_trail[k][1][52]], 1)
        corr *= character([(AC_STATES[k] >> 1) & 1], [mask_trail[k][1][56]], 1)
        corr *= character([(AC_STATES[k] >> 0) & 1], [mask_trail[k][1][60]], 1)

    
    for k in range(nb_rounds):
        for j in range(64):
            if mask_trail[k][0][j] == 0:
                continue
            conditions[k][j] = mask_trail[k][0][j]

    if corr > 0:
        return 1, log2(corr), conditions
    elif corr < 0:
        return -1, log2(-corr), conditions
    return 1, 0, []


def extract_keys_from_conditions(conditions, nb_rounds):
    k_lst = []
    for r in range(1, len(conditions)):
        for j in range(len(conditions[r])):
            if conditions[r][j] != []:
                if (63 - j) % 4 < 2:
                    ind = (63 - j) // 2 + (63 - j) % 2
                else:
                    ind = -1
                if ind >= 0 and r - 1 < len(key_map):
                    k_lst.append(f'k_{key_map[r-1][ind]}')
    return k_lst


def compute_distribution_from_trails(T, avg_p):
    print(avg_p)
    if len(T) == 0:
        return {}
    
    base_corr = (1) * avg_p
    
    unique_keys = set()
    for t in T:
        unique_keys.update(t['keys'])
    unique_keys = sorted(list(unique_keys))
    num_keys = len(unique_keys)
    
    print(f"  key num: {num_keys}")
    
    if num_keys == 0:
        
        total = sum(t['sign'] * (2 ** (t['corr'] - base_corr)) for t in T)
        return {round(total, 10): 1}
    
    key_to_idx = {k: i for i, k in enumerate(unique_keys)}
    total_space = 2 ** num_keys
    
    
    num_samples = 80000
    if total_space <= num_samples:
        X = np.array(list(itertools.product([0, 1], repeat=num_keys)))
        actual = total_space
    else:
        X = np.random.randint(0, 2, size=(num_samples, num_keys))
        actual = num_samples
    
    total_sum = np.zeros(actual)
    for t in T:
        k_indices = [key_to_idx[k] for k in t['keys']]
        if len(k_indices) > 0:
            xor_sum = np.sum(X[:, k_indices], axis=1) % 2
        else:
            xor_sum = np.zeros(actual)
        term_val = t['sign'] * (2 ** (t['corr'] - base_corr)) * ((-1) ** xor_sum)
        total_sum += term_val
    
    
    rounded = np.round(total_sum, 10)
    return dict(sorted(Counter(rounded.tolist()).items()))


def GIFT_MILP_Quasi_Diff(nb_rounds, mask_range):
    diff_trail = extract_diff_trail(DIFF_TRAIL_FILE, nb_rounds)
    sbox_inequalities = extract_inequalities_by_corr(SBOX_INEQUALITIES_DIR, SBOX_SIZE)
    model = Model("GIFT_SK_Quasi_Diff_MILP")
    
    u = model.addVars(nb_rounds, 2, 64, vtype=GRB.BINARY, name="m")
    Q = model.addVars(nb_rounds, 16, CORR_RANGE, vtype=GRB.BINARY, name="c")
    
    model.addConstrs(u[0, 0, l] == 0 for l in range(64))
    model.addConstrs(u[nb_rounds - 1, 1, l] == 0 for l in range(64))
    
    allowed_masks = set(mask_range)
    print(f"Applying mask range constraints (Allowed bits: {len(allowed_masks)})...")
    
    for r in range(nb_rounds):
        for before in range(2):
            for l in range(64):
                if (r, before, l) not in allowed_masks:
                    model.addConstr(u[r, before, 63 - l] == 0,
                                    name=f"mask_limit_{r}_{before}_{63-l}")
    
    for r in tqdm(range(nb_rounds)):
        for i in range(16):
            b = bin_to_int([diff_trail[r][1][4*i+l] for l in range(4)], SBOX_SIZE)
            a = bin_to_int([diff_trail[r][0][4*i+l] for l in range(4)], SBOX_SIZE)
            model.addConstr(quicksum(Q[r, i, corr] for corr in CORR_RANGE) == 1)
            for corr in CORR_RANGE:
                if sbox_inequalities[b][a][corr] == []:
                    model.addConstr(Q[r, i, corr] == 0)
                    continue
                for ineq in sbox_inequalities[b][a][corr]:
                    model.addConstr(
                        quicksum(ineq[0*SBOX_SIZE + l] * u[r, 1, 4*i + l] for l in BIT_RANGE) +
                        quicksum(ineq[1*SBOX_SIZE + l] * u[r, 0, 4*i + l] for l in BIT_RANGE) +
                        ineq[2*SBOX_SIZE] + 50000 * (1 - Q[r, i, corr]) >= 0
                    )
    
    for r in range(nb_rounds - 1):
        model.addConstrs(u[r, 1, l] == u[r + 1, 0, 63 - BIT_PERM[63 - l]] for l in range(64))
    
    model.addConstr(
        quicksum(Q[r, i, corr] * corr
                 for r in range(NB_ROUNDS) for i in range(16) for corr in CORR_RANGE)
        >= -500
    )
    model.setObjective(
        quicksum(Q[r, i, corr] * corr
                 for r in range(NB_ROUNDS) for i in range(16) for corr in CORR_RANGE),
        GRB.MAXIMIZE
    )
    
    model.params.PoolSearchMode = 2
    model.params.PoolSolutions = 2000000
    
    t1 = time.time()
    model.optimize()
    print(f"Time used: {time.time() - t1:.2f}s")
    print(f"Found {model.SolCount} trails")
    
    
    print("Extracting trails and computing correlations...")
    T = []
    avg_prob = None
    
    for m in tqdm(range(model.SolCount)):
        model.params.SolutionNumber = m
        mask_trail = [[[round(u[r, side, l].Xn) for l in range(64)]
                       for side in range(2)] for r in range(nb_rounds)]
        result = compute_correlation(diff_trail, mask_trail, nb_rounds)
        if result == "Error":
            continue
        sign, corr_log, conditions = result
        if avg_prob is None:
            avg_prob = corr_log
        keys = extract_keys_from_conditions(conditions, nb_rounds)
        T.append({'sign': sign, 'corr': corr_log, 'keys': keys})
    
    print(f"Valid trails: {len(T)}, base correlation: {avg_prob}")
    if(len(T)<10):
        print("DITRIBUTION: ",T)
    
    
    if avg_prob is None:
        return model.SolCount, {}
    
    distribution = compute_distribution_from_trails(T, avg_prob)
    print(f"Cluster distribution: {distribution}")
    
    return model.SolCount, distribution



def transform_var(var_str):    
    parts = var_str.split('_')
    
    
    prefix = parts[0]
    num1 = int(parts[1])
    num2 = int(parts[2])
    
    
    middle_val = 0 if prefix == 'x' else 1
    
    
    return (num1, middle_val, num2)


def trans_lst(MSK):
    transformed_list = [[transform_var(item) for item in sublist] for sublist in MSK]
    return transformed_list
